        fontSize: 16,
        border: "1px solid #d7c9c0",
        borderRadius: 4,
        width: "100%",
        maxWidth: 420,
        background: "#fff",
        boxSizing: "border-box",
    },
    button: {
        padding: "0.9rem 1.5rem",
        fontSize: 16,
        backgroundColor: "#2C2C2A",
        color: "#fff",
